with seed as (
 select * from jsonb_to_recordset('[{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Cells","slug":"cell-biology-foundations","title":"Cell Biology: Structure, Function and Organisation","content":"<h2>Learning objectives</h2><ul><li>Identify major cell structures.</li><li>Relate structures to functions.</li><li>Explain cell specialisation.</li></ul><h2>Cell structures</h2><p>Cells are the basic units of life. The selectively permeable membrane regulates exchange with the surroundings. Cytoplasm is the site of many chemical reactions. The nucleus contains genetic material and helps coordinate cell activities. Mitochondria release usable energy through aerobic respiration; ribosomes assemble proteins. Plant cells also have a cellulose wall for support, a large permanent vacuole and, in photosynthetic cells, chloroplasts containing chlorophyll.</p><h2>Plant and animal cells</h2><p>Both have a membrane, cytoplasm, genetic material and mitochondria. Typical plant cells have a cellulose wall and may contain chloroplasts and a large vacuole. Animal cells lack cellulose walls and chloroplasts. Not every plant cell contains chloroplasts: root hair cells are specialised for absorption and normally receive little light.</p><h2>Specialisation</h2><p>Root hair cells have an extended surface for water and mineral uptake. Red blood cells are adapted for oxygen transport, while neurones transmit impulses. Specialised cells form tissues and organs that work together.</p><h2>Key takeaways</h2><ul><li>Structure is related to function.</li><li>Plant and animal cells share structures but also differ.</li><li>Specialisation enables division of labour.</li></ul>","content_preview":"Cell structures, plant and animal cell differences, and specialised cells.","author":"AliverBiopharm","category":"Cells","tag":"cell-biology","read_time":"2 min read","word_count":175,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Ordinary Biology","group":"Form 1","learning_objectives":["Identify major cell structures","Relate structures to functions","Explain cell specialisation"],"key_terms":["cell membrane","mitochondria","ribosome"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Cell structures","anchor":"section-1-cell-structures"},{"level":2,"text":"Plant and animal cells","anchor":"section-2-plant-and-animal-cells"},{"level":2,"text":"Specialisation","anchor":"section-3-specialisation"},{"level":2,"text":"Key takeaways","anchor":"section-4-key-takeaways"}]},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Flowering Plants","slug":"flowering-plant-structure-and-reproduction","title":"Flowering Plants: Structure, Pollination and Seed Formation","content":"<h2>Learning objectives</h2><ul><li>Relate vegetative structures to their functions.</li><li>Identify flower reproductive parts.</li><li>Distinguish pollination from fertilisation.</li></ul><h2>Roots, stems and leaves</h2><p>Roots anchor plants and absorb water and mineral ions; root hairs increase surface area. Stems support leaves and flowers. Xylem carries water and minerals mainly upwards, while phloem transports dissolved products of photosynthesis. Leaves capture light and exchange gases through stomata regulated by guard cells.</p><h2>Flower structure</h2><p>Sepals protect the bud and petals may attract pollinators. The stamen consists of anther and filament; anthers produce pollen. The carpel includes stigma, style and ovary, with ovules inside the ovary.</p><h2>Reproduction</h2><p>Pollination is transfer of pollen from an anther to a stigma. Wind-pollinated flowers often have exposed anthers and feathery stigmas; insect-pollinated flowers may attract animals. Compatible pollen can germinate and grow a pollen tube towards an ovule. A male nucleus fuses with the egg nucleus during fertilisation. The fertilised ovule develops into a seed and the ovary commonly develops into a fruit. Germination usually requires water, oxygen and a suitable temperature.</p><h2>Remember</h2><p>Pollination moves pollen; fertilisation is fusion of nuclei. They are related but different processes.</p>","content_preview":"Plant structures, flower parts, pollination, fertilisation and seed formation.","author":"AliverBiopharm","category":"Flowering Plants","tag":"plant-reproduction","read_time":"2 min read","word_count":180,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Ordinary Biology","group":"Form 1","learning_objectives":["Relate plant structures to functions","Identify flower parts","Distinguish pollination from fertilisation"],"key_terms":["xylem","phloem","pollination"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Roots, stems and leaves","anchor":"section-1-roots-stems-and-leaves"},{"level":2,"text":"Flower structure","anchor":"section-2-flower-structure"},{"level":2,"text":"Reproduction","anchor":"section-3-reproduction"},{"level":2,"text":"Remember","anchor":"section-4-remember"}]},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Insects","slug":"insect-body-plan-and-adaptation","title":"Insects: Body Plan, Feeding and Adaptation","content":"<h2>Learning objectives</h2><ul><li>Describe defining insect features.</li><li>Explain feeding and gas-exchange adaptations.</li><li>Compare insect life cycles.</li></ul><h2>Body plan</h2><p>A typical adult insect has a head, thorax and abdomen, one pair of antennae, three pairs of jointed legs attached to the thorax, and a chitin-containing exoskeleton. Many have wings, though some are wingless. The exoskeleton protects and supports the body but cannot expand continuously, so growth involves moulting.</p><h2>Feeding and respiration</h2><p>Mouthparts reflect diet: grasshoppers chew plant material, butterflies take up nectar with a proboscis, and mosquitoes have piercing and sucking structures. Air commonly enters through spiracles and travels through branching tracheal tubes towards tissues. Insects have an open circulatory system, but haemolymph is not the main oxygen transport system in most insects.</p><h2>Development and importance</h2><p>Incomplete metamorphosis involves egg, nymph and adult. Complete metamorphosis involves egg, larva, pupa and adult. Larvae may use different food from adults, reducing competition. Insects pollinate plants, decompose organic matter and provide food for other animals; some transmit pathogens or damage crops. Their effects depend on species and context.</p><h2>Key takeaways</h2><ul><li>Adult insects have three pairs of legs.</li><li>Structures often reflect diet and habitat.</li><li>Metamorphosis changes how insects grow and use resources.</li></ul>","content_preview":"Insect anatomy, mouthpart adaptations, tracheal respiration and metamorphosis.","author":"AliverBiopharm","category":"Insects","tag":"insect-adaptation","read_time":"2 min read","word_count":165,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Ordinary Biology","group":"Form 1","learning_objectives":["Describe insect features","Explain adaptations","Compare life cycles"],"key_terms":["exoskeleton","spiracle","metamorphosis"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Body plan","anchor":"section-1-body-plan"},{"level":2,"text":"Feeding and respiration","anchor":"section-2-feeding-and-respiration"},{"level":2,"text":"Development and importance","anchor":"section-3-development-and-importance"},{"level":2,"text":"Key takeaways","anchor":"section-4-key-takeaways"}]},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Foundations of Pharmacy Practice","slug":"foundations-of-pharmacy-practice","title":"Foundations of Pharmacy Practice and Patient Safety","content":"<h2>Learning objectives</h2><ul><li>Describe core pharmacy responsibilities.</li><li>Apply a structured medicine-supply check.</li><li>Recognise when clarification or referral is needed.</li></ul><h2>Safe pharmacy practice</h2><p>Pharmacy practice supports safe, effective and appropriate medicine use. Depending on setting and scope, responsibilities include reviewing prescriptions, preparing or supplying medicines, counselling, identifying medicine-related problems, keeping records and referring patients.</p><h2>Before supply</h2><p>Verify the patient and medicine, strength, dosage form, directions, quantity and relevant dates. Check for inconsistencies, duplication, known allergy information and possible interactions using available information. If an important detail is unclear, pause and clarify with the authorised prescriber or supervisor instead of guessing or making an unauthorised change.</p><h2>Communication and confidentiality</h2><p>Use clear language to explain purpose, use, precautions and storage. Teach-back—asking a patient to repeat key instructions in their own words—can reveal misunderstandings. Access and share health information only for legitimate purposes consistent with law, consent and workplace policy. Keep records secure and work within your competence.</p><h2>Referral</h2><p>Escalate unclear prescriptions, potentially unsafe requests, serious symptoms or needs beyond the pharmacy’s role. Emergency warning signs require urgent local medical help. Educational knowledge does not replace clinical assessment or local protocols.</p><h2>Key takeaways</h2><ul><li>Clarify rather than guess.</li><li>Communicate clearly and protect confidentiality.</li><li>Work within scope and refer appropriately.</li></ul>","content_preview":"Pharmacy responsibilities, prescription screening, counselling, confidentiality and referral.","author":"AliverBiopharm","category":"Pharmacy Practice","tag":"pharmacy-safety","read_time":"2 min read","word_count":175,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Pharmacy","group":"Certificate","learning_objectives":["Describe pharmacy responsibilities","Apply a supply check","Recognise when to refer"],"key_terms":["patient safety","teach-back","confidentiality"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Safe pharmacy practice","anchor":"section-1-safe-pharmacy-practice"},{"level":2,"text":"Before supply","anchor":"section-2-before-supply"},{"level":2,"text":"Communication and confidentiality","anchor":"section-3-communication-and-confidentiality"},{"level":2,"text":"Referral","anchor":"section-4-referral"}]},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Drug Classification","slug":"drug-classes-and-classification","title":"Drug Classification: Therapeutic Use, Mechanism and Safety","content":"<h2>Learning objectives</h2><ul><li>Describe common medicine classification methods.</li><li>Distinguish therapeutic and pharmacological classes.</li><li>Explain why class membership does not prove equivalence.</li></ul><h2>Classification</h2><p>Medicines may be grouped by therapeutic use, biological target, chemical family, dosage form or legal supply category. A therapeutic class groups medicines by the problem they help manage; a pharmacological class groups them by shared mechanism or target. These categories overlap but are not identical.</p><h2>Examples and limits</h2><p>Analgesics relieve pain, antibiotics act against susceptible bacteria, antihistamines block histamine receptors, and antihypertensives lower blood pressure through different mechanisms. Medicines in the same broad class can differ in potency, duration, contraindications, interactions and adverse effects. Antibiotics are not automatically interchangeable because they differ in spectrum and approved uses.</p><h2>Legal categories and safe comparison</h2><p>Supply restrictions vary by jurisdiction and may change. Confirm legal status using current local legislation and an authoritative national reference. When comparing products, check active ingredient, strength, dosage form, route, indication and relevant risks. Similar names or broad class labels do not establish equivalence.</p><h2>Key takeaways</h2><ul><li>Classification depends on purpose.</li><li>Class membership does not guarantee equal safety or effect.</li><li>Use current local sources for legal supply decisions.</li></ul>","content_preview":"Medicine classification by therapeutic use, mechanism, chemical family and legal status.","author":"AliverBiopharm","category":"Pharmacology","tag":"drug-classification","read_time":"2 min read","word_count":150,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Pharmacy","group":"Certificate","learning_objectives":["Describe classification methods","Distinguish class types","Explain limits of class membership"],"key_terms":["therapeutic class","mechanism","interchangeability"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Classification","anchor":"section-1-classification"},{"level":2,"text":"Examples and limits","anchor":"section-2-examples-and-limits"},{"level":2,"text":"Legal categories and safe comparison","anchor":"section-3-legal-categories-and-safe-comparison"}]},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Basic Pharmacology","slug":"basic-pharmacology-principles","title":"Basic Pharmacology: Dose, Response and Medicine Effects","content":"<h2>Learning objectives</h2><ul><li>Distinguish pharmacokinetics from pharmacodynamics.</li><li>Explain dose-response relationships.</li><li>Recognise factors that alter response.</li></ul><h2>Pharmacokinetics and pharmacodynamics</h2><p>Pharmacokinetics describes what the body does to a medicine: absorption, distribution, metabolism and excretion (ADME). Pharmacodynamics describes what a medicine does to the body, including its target, mechanism and effects. Pharmacokinetics influences the concentration reaching a target; pharmacodynamics influences the response at that concentration.</p><h2>Dose, concentration and response</h2><p>Dose is the amount administered; concentration is the amount present in a defined volume or compartment. Absorption, distribution, metabolism, excretion, dosage form and time affect concentration. Effect often rises with concentration and may eventually approach a plateau.</p><h2>Potency, efficacy and safety</h2><p>Potency describes the amount needed for a specified effect under defined conditions. Efficacy describes the maximum response a medicine can produce in that system. A more potent medicine is not automatically safer or more effective in clinical use. Age, organ function, genetics, other medicines and clinical circumstances may alter response or adverse-effect risk.</p><h2>Safe application</h2><p>Use reliable references to review intended effects, time course, adverse effects and monitoring. Do not independently change a patient’s treatment based only on a classroom rule; treatment decisions require authorised clinical assessment and current guidance.</p><h2>Key takeaways</h2><ul><li>ADME describes medicine handling by the body.</li><li>Potency and efficacy are different.</li><li>Individual factors influence benefit and risk.</li></ul>","content_preview":"ADME, pharmacodynamics, dose-response relationships, potency, efficacy and patient variation.","author":"AliverBiopharm","category":"Pharmacology","tag":"basic-pharmacology","read_time":"2 min read","word_count":155,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Pharmacy","group":"Certificate","learning_objectives":["Distinguish pharmacokinetics and pharmacodynamics","Explain dose-response","Recognise response variation"],"key_terms":["ADME","potency","efficacy"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Pharmacokinetics and pharmacodynamics","anchor":"section-1-pharmacokinetics-and-pharmacodynamics"},{"level":2,"text":"Dose, concentration and response","anchor":"section-2-dose-concentration-and-response"},{"level":2,"text":"Potency, efficacy and safety","anchor":"section-3-potency-efficacy-and-safety"}]},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Compounding Techniques","slug":"pharmaceutical-compounding-techniques","title":"Pharmaceutical Compounding: Calculations, Process and Quality","content":"<h2>Learning objectives</h2><ul><li>Describe the purpose of compounding.</li><li>Explain calculation and quality checks.</li><li>Recognise documentation and stability requirements.</li></ul><h2>Plan before preparation</h2><p>Compounding prepares a medicine for a defined need when an authorised product is unsuitable or unavailable, within legal scope and local standards. Confirm formulation, final quantity, concentration, route and dosage form. Check ingredient quality, compatibility, stability, storage and the source of the formula. If details are unclear, seek qualified review rather than improvising.</p><h2>Calculations</h2><p>Use consistent units and verify conversions. For mass-per-volume concentration, concentration equals mass divided by final volume. For a simple dilution where solute amount is conserved, C₁V₁ = C₂V₂. V₂ is the final total solution volume, not merely the volume of diluent added. Independently check calculations where required, especially for high-risk ingredients or small quantities.</p><h2>Preparation and quality</h2><p>Follow an authorised procedure, use appropriate equipment and prevent contamination through suitable hygiene and environmental controls. Mix in the correct order to support uniformity. Inspect the preparation and document ingredients, quantities, method and required checks.</p><h2>Packaging and dating</h2><p>Choose compatible packaging and label the preparation, strength, route, directions, storage and warnings. Beyond-use dating must follow applicable standards and stability information; do not guess it from ingredient expiry dates alone.</p><h2>Key takeaways</h2><ul><li>Use authorised formulas and checked calculations.</li><li>Compatibility, stability and cleanliness are essential.</li><li>Follow local compounding standards.</li></ul>","content_preview":"Compounding workflow, dilution calculations, compatibility, cleanliness, labelling and stability.","author":"AliverBiopharm","category":"Pharmaceutics","tag":"compounding","read_time":"2 min read","word_count":150,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Pharmacy","group":"Diploma","learning_objectives":["Describe compounding purpose","Explain calculations","Recognise quality requirements"],"key_terms":["C1V1","compatibility","beyond-use date"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Plan before preparation","anchor":"section-1-plan-before-preparation"},{"level":2,"text":"Calculations","anchor":"section-2-calculations"},{"level":2,"text":"Preparation and quality","anchor":"section-3-preparation-and-quality"}]},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Clinical Pharmacy Practice","slug":"clinical-pharmacy-practice-and-medication-review","title":"Clinical Pharmacy Practice: Medication Review and Patient Communication","content":"<h2>Learning objectives</h2><ul><li>Gather a reliable medication history.</li><li>Identify medicine-related problems for review.</li><li>Communicate and escalate concerns appropriately.</li></ul><h2>Medication history</h2><p>A useful history includes prescription medicines, over-the-counter products, herbal preparations, supplements, allergies and previous adverse reactions. Confirm product, strength, dosage form, route, how it is actually taken and the reason for use when known. Ask about recently stopped medicines and products from different providers; one list may be incomplete.</p><h2>Structured review</h2><p>Consider whether each medicine has an indication, achieves its intended benefit, is practical to use and raises safety concerns. Look for duplication, possible interactions, contraindications, monitoring gaps, dosage-form difficulties, affordability or adherence barriers. These are prompts for assessment, not proof that a medicine is wrong; context and current guidance matter.</p><h2>Adherence and monitoring</h2><p>Missed doses may relate to cost, adverse effects, complex schedules, forgetfulness or difficulty obtaining a medicine. Ask open questions without blame. Monitoring may involve symptoms, clinical observations or laboratory measures. Document findings, uncertainty and communication with the care team. Escalate urgent concerns through local pathways and do not change treatment without appropriate authority.</p><h2>Patient-centred counselling</h2><p>Use plain language, invite questions and check understanding with teach-back. Protect confidentiality and share information only on an appropriate basis.</p><h2>Key takeaways</h2><ul><li>Reconcile what is prescribed with what is actually used.</li><li>Review effectiveness, safety and practicality.</li><li>Document and refer beyond your scope.</li></ul>","content_preview":"Medication history, medication review, adherence barriers, monitoring and patient communication.","author":"AliverBiopharm","category":"Clinical Pharmacy","tag":"medication-review","read_time":"2 min read","word_count":155,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Pharmacy","group":"Diploma","learning_objectives":["Gather medication history","Identify medication problems","Communicate and escalate"],"key_terms":["medication reconciliation","adherence","monitoring"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Medication history","anchor":"section-1-medication-history"},{"level":2,"text":"Structured review","anchor":"section-2-structured-review"},{"level":2,"text":"Adherence and monitoring","anchor":"section-3-adherence-and-monitoring"}]},{"level_name":"Pharmacy","group_name":"Degree","unit_name":"Therapeutics","slug":"therapeutics-principles-and-safe-use","title":"Therapeutics: Evidence, Individualisation and Monitoring","content":"<h2>Learning objectives</h2><ul><li>Describe an evidence-informed approach to therapy selection.</li><li>Explain individualisation.</li><li>Identify the role of monitoring and review.</li></ul><h2>Define the goal</h2><p>Therapeutics selects and uses interventions to prevent, relieve or manage disease and its consequences. Begin with a clear goal that matters to the patient and can be reviewed, such as symptom relief, reduced future risk, prevention of complications or improved function.</p><h2>Evidence and context</h2><p>Selection draws on current guidelines, clinical evidence, product information and professional judgement. Consider expected benefits, harms, alternatives, availability, cost and patient preferences. Guidelines inform decisions but do not replace assessment: contraindications, comorbidities and organ impairment can change what is appropriate.</p><h2>Individualisation</h2><p>People with the same diagnosis may respond differently. Relevant factors include age, kidney and liver function, pregnancy or breastfeeding, allergies, genetics, other medicines, previous response, adherence and practical circumstances. Route and regimen complexity affect whether treatment is workable. Patient-specific decisions require an authorised clinician using current local guidance.</p><h2>Monitoring and follow-up</h2><p>Decide how benefit and harm will be assessed, when review should occur and what findings require escalation. If goals are not reached, reassess diagnosis, treatment choice, actual use, interactions and access barriers with the care team. Explain uncertainty and document the agreed plan.</p><h2>Key takeaways</h2><ul><li>Choose treatment against a defined goal and relevant evidence.</li><li>Individual factors affect benefits and risks.</li><li>Monitoring and follow-up are part of treatment.</li></ul>","content_preview":"Therapeutic goals, evidence, patient-specific factors, monitoring and treatment review.","author":"AliverBiopharm","category":"Therapeutics","tag":"therapeutics","read_time":"2 min read","word_count":150,"display_order":1,"is_premium":false,"is_active":true,"metadata":{"curriculum_aligned":true,"level":"Pharmacy","group":"Degree","learning_objectives":["Describe evidence-informed selection","Explain individualisation","Identify monitoring needs"],"key_terms":["therapeutic goal","individualisation","monitoring"]},"toc":[{"level":2,"text":"Learning objectives","anchor":"section-0-learning-objectives"},{"level":2,"text":"Define the goal","anchor":"section-1-define-the-goal"},{"level":2,"text":"Evidence and context","anchor":"section-2-evidence-and-context"},{"level":2,"text":"Individualisation","anchor":"section-3-individualisation"},{"level":2,"text":"Monitoring and follow-up","anchor":"section-4-monitoring-and-follow-up"}]}]'::jsonb) as x(
 level_name text,group_name text,unit_name text,slug text,title text,content text,content_preview text,author text,category text,tag text,read_time text,word_count integer,display_order integer,is_premium boolean,is_active boolean,metadata jsonb,toc jsonb)
)
insert into public.notes(unit_id,slug,title,content,content_preview,author,category,tag,read_time,word_count,display_order,is_premium,is_active,metadata,toc)
select u.id,s.slug,s.title,s.content,s.content_preview,s.author,s.category,s.tag,s.read_time,s.word_count,s.display_order,s.is_premium,s.is_active,s.metadata,s.toc
from seed s join public.curriculum_levels l on l.display_name=s.level_name join public.curriculum_groups g on g.level_id=l.id and g.name=s.group_name join public.curriculum_units u on u.group_id=g.id and u.name=s.unit_name
on conflict(slug) do update set unit_id=excluded.unit_id,title=excluded.title,content=excluded.content,content_preview=excluded.content_preview,author=excluded.author,category=excluded.category,tag=excluded.tag,read_time=excluded.read_time,word_count=excluded.word_count,display_order=excluded.display_order,is_premium=excluded.is_premium,is_active=excluded.is_active,metadata=coalesce(public.notes.metadata,'{}'::jsonb)||excluded.metadata,toc=excluded.toc,updated_at=now();

insert into public.learning_content_links(curriculum_unit_id,content_type,content_id,relationship_type,is_primary,link_origin)
select n.unit_id,'note',n.id::text,'primary',true,'legacy_unit_id' from public.notes n where n.slug in ('cell-biology-foundations','flowering-plant-structure-and-reproduction','insect-body-plan-and-adaptation','foundations-of-pharmacy-practice','drug-classes-and-classification','basic-pharmacology-principles','pharmaceutical-compounding-techniques','clinical-pharmacy-practice-and-medication-review','therapeutics-principles-and-safe-use')
on conflict(curriculum_unit_id,content_type,content_id,relationship_type) do update set is_primary=true,link_origin='legacy_unit_id',updated_at=now();

with seed as (
 select * from jsonb_to_recordset('[{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Cells","question_text":"Which structure controls what enters and leaves a cell?","option_a":"Cell membrane","option_b":"Cell wall","option_c":"Ribosome","option_d":"Nucleolus","correct_option":"A","explanation":"The selectively permeable membrane regulates exchange.","difficulty":"easy","concept_name":"Cell structure","subtopic":"Membranes","learning_objective":"Identify membrane function"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Cells","question_text":"Which organelle is the main site of aerobic respiration?","option_a":"Chloroplast","option_b":"Mitochondrion","option_c":"Vacuole","option_d":"Golgi apparatus","correct_option":"B","explanation":"Mitochondria release usable energy through aerobic respiration.","difficulty":"easy","concept_name":"Cell structure","subtopic":"Organelles","learning_objective":"Relate mitochondria to respiration"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Cells","question_text":"Why do root hair cells normally lack chloroplasts?","option_a":"They cannot absorb water","option_b":"They have no membrane","option_c":"They receive little light and specialise in absorption","option_d":"They lack cytoplasm","correct_option":"C","explanation":"Root hair cells are adapted for water and mineral uptake.","difficulty":"medium","concept_name":"Cell specialisation","subtopic":"Root hair cells","learning_objective":"Explain cell adaptation"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Flowering Plants","question_text":"Which tissue carries water and mineral ions mainly from roots towards shoots?","option_a":"Phloem","option_b":"Epidermis","option_c":"Cambium only","option_d":"Xylem","correct_option":"D","explanation":"Xylem conducts water and dissolved mineral ions.","difficulty":"easy","concept_name":"Plant transport","subtopic":"Xylem","learning_objective":"Identify xylem function"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Flowering Plants","question_text":"Pollination is transfer of pollen from:","option_a":"Anther to stigma","option_b":"Ovary to ovule","option_c":"Root to leaf","option_d":"Stigma to root","correct_option":"A","explanation":"Pollination is pollen transfer; fertilisation is a later nuclear fusion.","difficulty":"easy","concept_name":"Plant reproduction","subtopic":"Pollination","learning_objective":"Define pollination"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Flowering Plants","question_text":"After fertilisation, the ovule commonly develops into a:","option_a":"Petal","option_b":"Seed","option_c":"Stigma","option_d":"Sepal","correct_option":"B","explanation":"The fertilised ovule develops into a seed.","difficulty":"easy","concept_name":"Plant reproduction","subtopic":"Seed formation","learning_objective":"Describe seed development"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Insects","question_text":"How many pairs of legs does a typical adult insect have?","option_a":"One","option_b":"Two","option_c":"Three","option_d":"Four","correct_option":"C","explanation":"Adult insects have three pairs of jointed legs.","difficulty":"easy","concept_name":"Insect structure","subtopic":"Body plan","learning_objective":"Recognise insect features"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Insects","question_text":"Insects exchange gases mainly through:","option_a":"Lungs and alveoli","option_b":"Gills in every species","option_c":"A closed blood-vessel network","option_d":"Spiracles and branching tracheal tubes","correct_option":"D","explanation":"Air enters spiracles and travels through tracheal tubes.","difficulty":"medium","concept_name":"Insect physiology","subtopic":"Gas exchange","learning_objective":"Explain insect respiration"},{"level_name":"Ordinary Biology","group_name":"Form 1","unit_name":"Insects","question_text":"Which sequence represents complete metamorphosis?","option_a":"Egg, nymph, adult","option_b":"Egg, larva, pupa, adult","option_c":"Larva, egg, adult, pupa","option_d":"Egg, pupa, nymph, adult","correct_option":"B","explanation":"Complete metamorphosis includes egg, larva, pupa and adult.","difficulty":"easy","concept_name":"Insect development","subtopic":"Metamorphosis","learning_objective":"Compare insect life cycles"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Foundations of Pharmacy Practice","question_text":"A prescription has an unclear strength. What is safest?","option_a":"Guess the common strength","option_b":"Supply and explain later","option_c":"Clarify with the authorised prescriber or supervisor","option_d":"Change to an available product without discussion","correct_option":"C","explanation":"Unclear prescription details should be clarified, not guessed.","difficulty":"easy","concept_name":"Professional practice","subtopic":"Prescription screening","learning_objective":"Apply safe escalation"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Foundations of Pharmacy Practice","question_text":"Which approach best checks patient understanding?","option_a":"Ask them to repeat key instructions in their own words","option_b":"Ask only if they heard you","option_c":"Use more technical terms","option_d":"Assume silence means agreement","correct_option":"A","explanation":"Teach-back can reveal misunderstandings respectfully.","difficulty":"easy","concept_name":"Communication","subtopic":"Teach-back","learning_objective":"Check understanding"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Foundations of Pharmacy Practice","question_text":"When may confidential patient information be shared?","option_a":"Whenever a friend asks","option_b":"Whenever convenient","option_c":"With anyone at work","option_d":"For a legitimate authorised purpose consistent with law and policy","correct_option":"D","explanation":"Confidential information needs an appropriate lawful basis for sharing.","difficulty":"medium","concept_name":"Professional ethics","subtopic":"Confidentiality","learning_objective":"Apply confidentiality"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Drug Classification","question_text":"A group of medicines sharing a biological mechanism is a:","option_a":"Dosage form","option_b":"Pharmacological class","option_c":"Storage category only","option_d":"Brand family always","correct_option":"B","explanation":"Pharmacological classes group medicines by mechanism or target.","difficulty":"easy","concept_name":"Drug classification","subtopic":"Mechanism","learning_objective":"Distinguish class types"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Drug Classification","question_text":"Why are medicines in one therapeutic class not automatically interchangeable?","option_a":"They always have identical ingredients","option_b":"Class guarantees equal safety","option_c":"They may differ in strength, contraindications, interactions and approved uses","option_d":"They all have the same dosage form","correct_option":"C","explanation":"Broad class membership does not establish equivalence.","difficulty":"medium","concept_name":"Drug classification","subtopic":"Interchangeability","learning_objective":"Evaluate medicine comparisons"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Drug Classification","question_text":"Which source should confirm current legal supply category?","option_a":"Social media comment","option_b":"Old note from another country","option_c":"Brand advertisement alone","option_d":"Current local legislation and an authoritative national reference","correct_option":"D","explanation":"Legal status varies and may change; use current local sources.","difficulty":"medium","concept_name":"Regulation","subtopic":"Medicine supply","learning_objective":"Find authoritative legal information"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Basic Pharmacology","question_text":"Pharmacokinetics is commonly summarised as:","option_a":"Absorption, distribution, metabolism and excretion","option_b":"Receptor binding only","option_c":"Adverse effects only","option_d":"Brand name","correct_option":"A","explanation":"ADME describes the body''s handling of a medicine.","difficulty":"easy","concept_name":"Pharmacology","subtopic":"ADME","learning_objective":"Define pharmacokinetics"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Basic Pharmacology","question_text":"Efficacy refers to a medicine''s ability to:","option_a":"Dissolve in every solvent","option_b":"Produce a maximum response in a defined system","option_c":"Reach market quickly","option_d":"Avoid all adverse effects","correct_option":"B","explanation":"Efficacy is the maximum response possible in the studied system.","difficulty":"medium","concept_name":"Pharmacology","subtopic":"Efficacy","learning_objective":"Distinguish efficacy"},{"level_name":"Pharmacy","group_name":"Certificate","unit_name":"Basic Pharmacology","question_text":"Why can a medicine have different effects in different people?","option_a":"Every body responds identically","option_b":"Only brand name matters","option_c":"Age, organ function and other medicines can alter exposure or response","option_d":"Dose never matters","correct_option":"C","explanation":"Patient factors and interactions can alter response and risk.","difficulty":"medium","concept_name":"Pharmacology","subtopic":"Individual variation","learning_objective":"Explain response variation"},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Compounding Techniques","question_text":"Which equation can be used for a simple dilution with conserved solute?","option_a":"C₁ + V₁ = C₂ + V₂","option_b":"C₁V₁ = C₂V₂","option_c":"C₁C₂ = V₁ + V₂","option_d":"V₁ − V₂ = C₁C₂","correct_option":"B","explanation":"C₁V₁ = C₂V₂ when solute amount is conserved and units match.","difficulty":"easy","concept_name":"Compounding","subtopic":"Dilution","learning_objective":"Apply dilution equation"},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Compounding Techniques","question_text":"In a dilution, V₂ normally means:","option_a":"Stock volume only","option_b":"Empty container capacity","option_c":"Volume of solvent added only","option_d":"Final total solution volume","correct_option":"D","explanation":"V₂ is final total solution volume.","difficulty":"medium","concept_name":"Compounding","subtopic":"Final volume","learning_objective":"Interpret dilution variables"},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Compounding Techniques","question_text":"Why not guess a beyond-use date from ingredient expiry dates alone?","option_a":"Formulation stability and applicable standards also matter","option_b":"Every product lasts a year","option_c":"Expiry dates are irrelevant","option_d":"Labels can be omitted","correct_option":"A","explanation":"Beyond-use dating depends on formulation, storage, stability evidence and standards.","difficulty":"medium","concept_name":"Compounding","subtopic":"Stability","learning_objective":"Explain beyond-use dating"},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Clinical Pharmacy Practice","question_text":"A comprehensive medication history includes:","option_a":"Prescription medicines only","option_b":"Morning medicines only","option_c":"Prescription, OTC, herbal and supplement products","option_d":"Products from one pharmacy only","correct_option":"C","explanation":"A complete history includes relevant products and recent changes.","difficulty":"easy","concept_name":"Clinical pharmacy","subtopic":"Medication history","learning_objective":"Gather medication history"},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Clinical Pharmacy Practice","question_text":"A patient misses doses because the schedule is confusing. What is the best first response?","option_a":"Accuse them of carelessness","option_b":"Explore the difficulty and clarify with the care team","option_c":"Tell them to double the next dose","option_d":"Ignore the issue","correct_option":"B","explanation":"A respectful conversation identifies barriers; changes need appropriate professional review.","difficulty":"medium","concept_name":"Clinical pharmacy","subtopic":"Adherence","learning_objective":"Respond to adherence barriers"},{"level_name":"Pharmacy","group_name":"Diploma","unit_name":"Clinical Pharmacy Practice","question_text":"Why document a medication review?","option_a":"To replace all communication","option_b":"To guarantee no future problem","option_c":"To avoid recording uncertainty","option_d":"To record findings, actions and unresolved concerns","correct_option":"D","explanation":"Documentation supports continuity and follow-up.","difficulty":"easy","concept_name":"Clinical pharmacy","subtopic":"Documentation","learning_objective":"Explain documentation"},{"level_name":"Pharmacy","group_name":"Degree","unit_name":"Therapeutics","question_text":"A useful therapeutic plan should begin with:","option_a":"A defined goal that can be assessed","option_b":"The most expensive medicine","option_c":"A brand name before assessment","option_d":"Avoiding follow-up","correct_option":"A","explanation":"A defined goal guides selection and monitoring.","difficulty":"easy","concept_name":"Therapeutics","subtopic":"Goals","learning_objective":"Define therapeutic objective"},{"level_name":"Pharmacy","group_name":"Degree","unit_name":"Therapeutics","question_text":"Why do guidelines not replace individual assessment?","option_a":"They contain no evidence","option_b":"Every patient has identical risks","option_c":"Contraindications, comorbidities and preferences affect appropriateness","option_d":"They apply only to tablets","correct_option":"C","explanation":"Guidelines inform decisions but patient-specific factors still matter.","difficulty":"medium","concept_name":"Therapeutics","subtopic":"Individualisation","learning_objective":"Apply guidelines to context"},{"level_name":"Pharmacy","group_name":"Degree","unit_name":"Therapeutics","question_text":"If a treatment goal is not achieved, what is an appropriate next step?","option_a":"Automatically double the dose","option_b":"Reassess diagnosis, treatment, use and monitoring with the care team","option_c":"Stop all other medicines","option_d":"Assume the patient is at fault","correct_option":"B","explanation":"Structured review looks for explanations before treatment changes.","difficulty":"medium","concept_name":"Therapeutics","subtopic":"Monitoring","learning_objective":"Interpret inadequate response"}]'::jsonb) as x(
 level_name text,group_name text,unit_name text,question_text text,option_a text,option_b text,option_c text,option_d text,correct_option char(1),explanation text,difficulty text,concept_name text,subtopic text,learning_objective text)
)
insert into public.quiz_questions(question_text,option_a,option_b,option_c,option_d,correct_option,explanation,difficulty,is_active,unit_id,concept_name,subtopic,learning_objective,status,version,is_note_practice)
select s.question_text,s.option_a,s.option_b,s.option_c,s.option_d,s.correct_option,s.explanation,s.difficulty,true,u.id,s.concept_name,s.subtopic,s.learning_objective,'published',1,true
from seed s join public.curriculum_levels l on l.display_name=s.level_name join public.curriculum_groups g on g.level_id=l.id and g.name=s.group_name join public.curriculum_units u on u.group_id=g.id and u.name=s.unit_name
where not exists(select 1 from public.quiz_questions q where q.unit_id=u.id and lower(trim(q.question_text))=lower(trim(s.question_text)));
commit;